    tool("write_file", "Overwrite a file with new contents.", {
      path: { type: "string" },
      contents: { type: "string" },
    }, ["path", "contents"]),
    tool("run_tests", "Run the test suite and return the results.", {}),
    SUBMIT_TOOL,
